// Audio chiptune generado con WebAudio. Sin archivos externos.
const MELODY = [
  72, 76, 79, 76, 72, 76, 79, 84,
  83, 79, 76, 79, 72, 0, 74, 76,
  77, 81, 84, 81, 77, 76, 74, 72,
  74, 76, 77, 79, 76, 0, 72, 0,
]
const BASS = [48, 48, 43, 43, 41, 41, 43, 43]
const STEP = 0.16

const midiToFreq = (n) => 440 * Math.pow(2, (n - 69) / 12)

export class AudioEngine {
  constructor() {
    this.ctx = null
    this.enabled = localStorage.getItem('sapobros.sound') !== 'off'
    this.musicWanted = false
    this.master = null
    this.musicGain = null
    this.sfxGain = null
    this.step = 0
    this.nextTime = 0
    this.noiseBuffer = null
    this.playing = false
  }

  ensure() {
    if (!this.ctx) {
      const Ctx = window.AudioContext || window.webkitAudioContext
      if (!Ctx) return false
      this.ctx = new Ctx()
      this.master = this.ctx.createGain()
      this.master.gain.value = this.enabled ? 0.6 : 0
      this.master.connect(this.ctx.destination)
      this.musicGain = this.ctx.createGain()
      this.musicGain.gain.value = 0.5
      this.musicGain.connect(this.master)
      this.sfxGain = this.ctx.createGain()
      this.sfxGain.gain.value = 0.9
      this.sfxGain.connect(this.master)
      const len = this.ctx.sampleRate * 0.4
      const buffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate)
      const data = buffer.getChannelData(0)
      for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1
      this.noiseBuffer = buffer
    }
    if (this.ctx.state === 'suspended') this.ctx.resume()
    return true
  }

  unlock() {
    this.ensure()
    if (this.musicWanted && this.ctx) this.playing = true
  }

  setEnabled(on) {
    this.enabled = on
    localStorage.setItem('sapobros.sound', on ? 'on' : 'off')
    if (this.ctx) {
      this.master.gain.cancelScheduledValues(this.ctx.currentTime)
      this.master.gain.linearRampToValueAtTime(on ? 0.6 : 0, this.ctx.currentTime + 0.08)
    }
    if (on) this.unlock()
  }

  toggle() {
    this.setEnabled(!this.enabled)
    return this.enabled
  }

  tone(freq, when, dur, type = 'square', vol = 0.08, slideTo = null, dest = null) {
    if (!this.ctx) return
    const osc = this.ctx.createOscillator()
    const gain = this.ctx.createGain()
    osc.type = type
    osc.frequency.setValueAtTime(freq, when)
    if (slideTo) osc.frequency.exponentialRampToValueAtTime(Math.max(20, slideTo), when + dur)
    gain.gain.setValueAtTime(0.0001, when)
    gain.gain.exponentialRampToValueAtTime(vol, when + 0.01)
    gain.gain.exponentialRampToValueAtTime(0.0001, when + dur)
    osc.connect(gain)
    gain.connect(dest || this.sfxGain)
    osc.start(when)
    osc.stop(when + dur + 0.02)
  }

  noise(when, dur, vol = 0.12, freq = 900) {
    if (!this.ctx || !this.noiseBuffer) return
    const src = this.ctx.createBufferSource()
    src.buffer = this.noiseBuffer
    const filter = this.ctx.createBiquadFilter()
    filter.type = 'bandpass'
    filter.frequency.value = freq
    const gain = this.ctx.createGain()
    gain.gain.setValueAtTime(vol, when)
    gain.gain.exponentialRampToValueAtTime(0.0001, when + dur)
    src.connect(filter)
    filter.connect(gain)
    gain.connect(this.sfxGain)
    src.start(when)
    src.stop(when + dur)
  }

  jump() {
    if (!this.ensure()) return
    const t = this.ctx.currentTime
    this.tone(330, t, 0.14, 'square', 0.07, 620)
  }

  coin() {
    if (!this.ensure()) return
    const t = this.ctx.currentTime
    this.tone(988, t, 0.07, 'square', 0.06)
    this.tone(1319, t + 0.07, 0.16, 'square', 0.06)
  }

  stomp() {
    if (!this.ensure()) return
    const t = this.ctx.currentTime
    this.tone(180, t, 0.12, 'triangle', 0.12, 60)
    this.noise(t, 0.08, 0.1, 700)
  }

  bump() {
    if (!this.ensure()) return
    const t = this.ctx.currentTime
    this.tone(140, t, 0.07, 'square', 0.08, 90)
  }

  brick() {
    if (!this.ensure()) return
    const t = this.ctx.currentTime
    this.noise(t, 0.14, 0.16, 500)
    this.tone(220, t, 0.1, 'square', 0.06, 80)
  }

  power() {
    if (!this.ensure()) return
    const t = this.ctx.currentTime
    ;[523, 659, 784, 1047].forEach((f, i) => this.tone(f, t + i * 0.07, 0.12, 'square', 0.07))
  }

  checkpoint() {
    if (!this.ensure()) return
    const t = this.ctx.currentTime
    this.tone(784, t, 0.1, 'triangle', 0.08)
    this.tone(1047, t + 0.1, 0.22, 'triangle', 0.08)
  }

  shieldPop() {
    if (!this.ensure()) return
    const t = this.ctx.currentTime
    this.noise(t, 0.18, 0.14, 1400)
    this.tone(600, t, 0.16, 'sine', 0.08, 200)
  }

  hurt() {
    if (!this.ensure()) return
    const t = this.ctx.currentTime
    this.tone(320, t, 0.3, 'sawtooth', 0.09, 80)
  }

  death() {
    if (!this.ensure()) return
    const t = this.ctx.currentTime
    ;[392, 330, 262, 196].forEach((f, i) => this.tone(f, t + i * 0.13, 0.18, 'square', 0.08))
  }

  win() {
    if (!this.ensure()) return
    const t = this.ctx.currentTime
    const notes = [523, 659, 784, 1047, 784, 1047, 1319]
    notes.forEach((f, i) => this.tone(f, t + i * 0.12, i === notes.length - 1 ? 0.6 : 0.14, 'square', 0.08))
    this.tone(262, t, 0.8, 'triangle', 0.06)
  }

  startMusic() {
    this.musicWanted = true
    if (!this.ensure()) return
    this.playing = true
    this.step = 0
    this.nextTime = this.ctx.currentTime + 0.1
  }

  stopMusic() {
    this.musicWanted = false
    this.playing = false
  }

  tick() {
    if (!this.ctx || !this.playing || !this.enabled) return
    while (this.nextTime < this.ctx.currentTime + 0.2) {
      const i = this.step % 32
      const note = MELODY[i]
      if (note) {
        this.tone(midiToFreq(note), this.nextTime, STEP * 0.82, 'square', 0.035, null, this.musicGain)
      }
      if (i % 4 === 0) {
        const b = BASS[(i / 4) % BASS.length]
        this.tone(midiToFreq(b), this.nextTime, STEP * 1.6, 'triangle', 0.05, null, this.musicGain)
      }
      if (i % 2 === 0) this.noise(this.nextTime, 0.03, 0.012, 6000)
      this.nextTime += STEP
      this.step++
    }
  }
}

:root {
  --ink: #0d1b24;
  --ink-2: #142b38;
  --cream: #fff4d6;
  --green: #7fe06a;
  --green-deep: #57b84c;
  --gold: #ffd873;
  --orange: #ff8a3d;
  --blue: #8fd4ef;
  --shadow: 0 18px 50px rgba(0, 0, 0, .45);
  --mono: ui-monospace, "SF Mono", "Cascadia Mono", "Roboto Mono", Menlo, Consolas, monospace;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
}

body {
  background:
    radial-gradient(1200px 700px at 50% -10%, #1d4356 0%, rgba(29, 67, 86, 0) 60%),
    radial-gradient(900px 600px at 85% 110%, #173a2c 0%, rgba(23, 58, 44, 0) 55%),
    linear-gradient(180deg, #0a1620 0%, #0d2230 45%, #091820 100%);
  color: var(--cream);
  font-family: var(--mono);
  overflow: hidden;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
  touch-action: manipulation;
}

body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  background-image:
    linear-gradient(rgba(255, 255, 255, .025) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, .025) 1px, transparent 1px);
  background-size: 32px 32px;
  mask-image: radial-gradient(circle at 50% 45%, #000 0%, transparent 75%);
}

#app {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
  height: 100dvh;
  padding: calc(12px + env(safe-area-inset-top)) 12px calc(12px + env(safe-area-inset-bottom));
}

#stage {
  width: min(96vw, 1120px, calc((100dvh - 120px) * 1.7647));
}

#frame {
  position: relative;
  width: 100%;
  aspect-ratio: 480 / 272;
  overflow: hidden;
  border-radius: 18px;
  border: 3px solid #07131a;
  outline: 2px solid rgba(143, 231, 106, .16);
  outline-offset: 3px;
  box-shadow: var(--shadow), inset 0 0 0 1px rgba(255, 255, 255, .06);
  background: #0d2230;
  isolation: isolate;
}

#game {
  display: block;
  width: 100%;
  height: 100%;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
}

/* ------------------------------- HUD ------------------------------------ */
#hud {
  position: absolute;
  inset: 0 0 auto 0;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  padding: 9px 12px;
  font-size: clamp(9px, 1.15vw, 14px);
  font-weight: 700;
  letter-spacing: .08em;
  pointer-events: none;
  opacity: 0;
  transition: opacity .25s ease;
  text-shadow: 0 2px 0 rgba(0, 0, 0, .55);
  background: linear-gradient(180deg, rgba(4, 14, 20, .42), rgba(4, 14, 20, 0));
}

#frame.playing #hud { opacity: 1; }

.hud-group {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.hud-center {
  flex: 1;
  justify-content: center;
  opacity: .78;
  font-size: .82em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.hud-right { justify-content: flex-end; }

.hud-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 8px;
  border-radius: 7px;
  background: rgba(7, 22, 29, .57);
  border: 1px solid rgba(255, 244, 214, .18);
  box-shadow: 0 2px 0 rgba(0, 0, 0, .25);
  font-variant-numeric: tabular-nums;
}

.heart { color: #ff6b6b; font-size: 1.15em; line-height: 1; }

.coin-dot {
  width: 11px;
  height: 11px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #fff6c9, #ffd23f 45%, #c98b14 100%);
  box-shadow: 0 0 0 1px rgba(0, 0, 0, .35);
}

.clock { color: var(--blue); }

#hud-time-chip.warn {
  color: #ff9a9a;
  animation: blink .7s steps(2, start) infinite;
}

@keyframes blink { 50% { opacity: .35; } }

/* --------------------------- Botones superiores -------------------------- */
#top-buttons {
  position: absolute;
  right: 10px;
  bottom: 10px;
  display: flex;
  gap: 7px;
  z-index: 6;
  opacity: 0;
  transition: opacity .2s ease;
}

#frame.playing #top-buttons { opacity: .9; }

.icon-btn {
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  border-radius: 9px;
  border: 1px solid rgba(255, 244, 214, .22);
  background: rgba(7, 22, 29, .62);
  color: var(--cream);
  font-family: var(--mono);
  font-size: 14px;
  line-height: 1;
  cursor: pointer;
  backdrop-filter: blur(6px);
  transition: transform .12s ease, background .12s ease;
}

.icon-btn:hover { background: rgba(20, 48, 60, .9); transform: translateY(-1px); }
.icon-btn:active { transform: translateY(1px); }

/* --------------------------- Controles táctiles --------------------------- */
#touch {
  position: absolute;
  inset: auto 0 0 0;
  display: none;
  justify-content: space-between;
  padding: 0 14px calc(12px + env(safe-area-inset-bottom));
  pointer-events: none;
  z-index: 5;
}

body.touch #touch { display: flex; }

.touch-side {
  display: flex;
  align-items: flex-end;
  gap: 10px;
  pointer-events: none;
}

.tbtn {
  pointer-events: auto;
  width: clamp(52px, 9vh, 68px);
  height: clamp(52px, 9vh, 68px);
  border-radius: 50%;
  border: 2px solid rgba(255, 244, 214, .35);
  background: rgba(10, 30, 38, .55);
  color: var(--cream);
  font-family: var(--mono);
  font-size: clamp(18px, 3vh, 26px);
  font-weight: 700;
  display: grid;
  place-items: center;
  backdrop-filter: blur(5px);
  touch-action: none;
  box-shadow: 0 4px 0 rgba(0, 0, 0, .35);
  transition: transform .06s linear, background .1s ease;
}

.tbtn:active, .tbtn.down {
  background: rgba(87, 184, 76, .75);
  transform: translateY(2px) scale(.96);
  box-shadow: 0 2px 0 rgba(0, 0, 0, .35);
}

.tbtn-jump {
  width: clamp(62px, 11vh, 82px);
  height: clamp(62px, 11vh, 82px);
  background: rgba(244, 185, 63, .32);
  border-color: rgba(255, 216, 115, .65);
}

.tbtn-run {
  background: rgba(47, 111, 158, .42);
  border-color: rgba(143, 212, 239, .55);
}

/* ------------------------------- Pantallas ------------------------------- */
.screen {
  position: absolute;
  inset: 0;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: clamp(8px, 2.5vw, 26px);
  background:
    radial-gradient(70% 90% at 50% 20%, rgba(10, 34, 42, .35), rgba(4, 12, 17, .82) 75%),
    linear-gradient(180deg, rgba(4, 14, 20, .25), rgba(4, 14, 20, .68));
  backdrop-filter: blur(2px);
  overflow: auto;
}

.screen.hidden { display: none; }

.title-card {
  width: min(460px, 100%);
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: clamp(4px, 1.2vh, 10px);
  animation: pop .45s cubic-bezier(.2, 1.4, .4, 1) both;
}

.mascot {
  width: clamp(46px, 11vh, 86px);
  aspect-ratio: 1;
  filter: drop-shadow(0 8px 12px rgba(0, 0, 0, .35));
  animation: bob 2.6s ease-in-out infinite;
}

.mascot svg { width: 100%; height: 100%; display: block; }

@keyframes bob {
  0%, 100% { transform: translateY(0) rotate(-2deg); }
  50% { transform: translateY(-7px) rotate(2deg); }
}

.logo {
  margin: 0;
  display: flex;
  align-items: baseline;
  gap: .12em;
  font-family: var(--mono);
  font-weight: 900;
  font-size: clamp(38px, 8.4vh, 74px);
  line-height: .9;
  letter-spacing: -.03em;
  filter: drop-shadow(0 6px 0 rgba(0, 0, 0, .28));
}

.logo-sapo {
  color: var(--green);
  text-shadow:
    3px 0 0 #143a1c, -3px 0 0 #143a1c, 0 3px 0 #143a1c, 0 -3px 0 #143a1c,
    2px 2px 0 #143a1c, -2px 2px 0 #143a1c, 2px -2px 0 #143a1c, -2px -2px 0 #143a1c,
    0 7px 0 #0b2412;
}

.logo-bros {
  color: var(--gold);
  text-shadow:
    3px 0 0 #4a2c06, -3px 0 0 #4a2c06, 0 3px 0 #4a2c06, 0 -3px 0 #4a2c06,
    2px 2px 0 #4a2c06, -2px 2px 0 #4a2c06, 2px -2px 0 #4a2c06, -2px -2px 0 #4a2c06,
    0 7px 0 #2e1b03;
}

.logo-sub {
  margin: -2px 0 0;
  font-size: clamp(8px, 1.7vh, 13px);
  letter-spacing: .48em;
  color: #b9e9d0;
  opacity: .9;
}

.tagline {
  margin: 2px 0 0;
  font-size: clamp(10px, 1.9vh, 14px);
  color: #d8ecd8;
  opacity: .85;
}

.btn {
  font-family: var(--mono);
  font-weight: 800;
  letter-spacing: .12em;
  font-size: clamp(11px, 2vh, 15px);
  border-radius: 10px;
  border: 2px solid #07131a;
  padding: clamp(9px, 1.8vh, 14px) clamp(22px, 4vw, 34px);
  cursor: pointer;
  transition: transform .1s ease, box-shadow .1s ease, filter .15s ease;
}

.btn.primary {
  color: #0e2612;
  background: linear-gradient(180deg, #a9f187, #6bd155 55%, #4bb33d);
  box-shadow: 0 5px 0 #2c7425, 0 12px 20px rgba(0, 0, 0, .35);
}

.btn.primary:hover { filter: brightness(1.06); transform: translateY(-1px); }
.btn.primary:active { transform: translateY(4px); box-shadow: 0 1px 0 #2c7425; }

.btn.ghost {
  color: var(--cream);
  background: rgba(255, 255, 255, .07);
  border-color: rgba(255, 244, 214, .3);
  box-shadow: 0 4px 0 rgba(0, 0, 0, .35);
}

.btn.ghost:hover { background: rgba(255, 255, 255, .14); }

.title-controls {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 6px 14px;
  font-size: clamp(8px, 1.55vh, 12px);
  color: #cfe6d8;
  opacity: .8;
}

kbd {
  font-family: var(--mono);
  font-size: .92em;
  padding: 2px 5px;
  margin-right: 2px;
  border-radius: 4px;
  border: 1px solid rgba(255, 255, 255, .3);
  border-bottom-width: 2px;
  background: rgba(255, 255, 255, .1);
  color: #fff8e2;
}

.best {
  margin: 0;
  font-size: clamp(8px, 1.6vh, 12px);
  letter-spacing: .16em;
  opacity: .6;
}

.best strong { color: var(--gold); }

/* Paneles de pausa / fin */
.panel {
  width: min(390px, 100%);
  padding: clamp(16px, 3.2vh, 30px) clamp(18px, 4vw, 34px);
  text-align: center;
  border-radius: 16px;
  background: linear-gradient(180deg, rgba(17, 44, 55, .96), rgba(8, 24, 32, .97));
  border: 2px solid rgba(143, 231, 106, .28);
  box-shadow: 0 22px 50px rgba(0, 0, 0, .55), inset 0 1px 0 rgba(255, 255, 255, .08);
  animation: pop .3s cubic-bezier(.2, 1.4, .4, 1) both;
}

@keyframes pop {
  from { opacity: 0; transform: scale(.92) translateY(8px); }
  to { opacity: 1; transform: scale(1) translateY(0); }
}

.panel h2 {
  margin: 0;
  font-size: clamp(24px, 5.4vh, 42px);
  letter-spacing: .06em;
  color: var(--green);
  text-shadow: 0 3px 0 #123a1a;
}

.panel h2.danger {
  color: #ff8a8a;
  text-shadow: 0 3px 0 #4a1414;
}

.panel.victory h2 {
  color: var(--gold);
  text-shadow: 0 3px 0 #4a3206;
}

.panel-sub {
  margin: 6px 0 clamp(10px, 2vh, 18px);
  font-size: clamp(9px, 1.8vh, 13px);
  color: #cfe6d8;
  opacity: .8;
}

.panel-actions {
  display: flex;
  gap: 10px;
  justify-content: center;
  flex-wrap: wrap;
}

.panel-actions .btn { flex: 1 1 auto; }

.mini-hint {
  margin: 14px 0 0;
  font-size: clamp(8px, 1.5vh, 11px);
  opacity: .5;
  letter-spacing: .1em;
}

.stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin: 0 0 clamp(14px, 2.6vh, 22px);
}

.stats div {
  padding: 9px 4px;
  border-radius: 9px;
  background: rgba(255, 255, 255, .05);
  border: 1px solid rgba(255, 255, 255, .09);
}

.stats span {
  display: block;
  font-size: clamp(7px, 1.4vh, 10px);
  letter-spacing: .12em;
  opacity: .65;
  margin-bottom: 4px;
}

.stats strong {
  font-size: clamp(14px, 2.6vh, 20px);
  color: var(--gold);
  font-variant-numeric: tabular-nums;
}

/* ------------------------------- Footer --------------------------------- */
#footer-hint {
  margin: 0;
  font-size: 11px;
  letter-spacing: .06em;
  color: #9fc4b6;
  opacity: .55;
  text-align: center;
}

.show-sm { display: none; }

@media (max-width: 720px) {
  #stage { width: min(98vw, calc((100dvh - 70px) * 1.7647)); }
  #footer-hint { font-size: 10px; }
  .hide-sm { display: none; }
  .show-sm { display: inline; }
}

@media (pointer: coarse) {
  .hide-sm { display: none; }
  .show-sm { display: inline; }
}

@media (max-height: 470px) {
  #app { gap: 8px; padding-top: 6px; padding-bottom: 6px; }
  #footer-hint { display: none; }
  #stage { width: min(96vw, 1120px, calc((100dvh - 24px) * 1.7647)); }
  .title-card { gap: 2px; }
  .mascot { width: 44px; }
  .tagline { display: none; }
  .title-controls { font-size: 9px; }
}

@media (max-height: 380px) {
  .title-controls, .best { display: none; }
  .mascot { display: none; }
  .panel-sub { margin-bottom: 8px; }
  .mini-hint { display: none; }
}

import { createLevel, T, TILE, SOLID, GROUND_ROW } from './level.js'

const VIEW_W = 480
const VIEW_H = 272
const STEP = 1 / 60
const GRAVITY = 1500
const MAX_FALL = 560

const clamp = (v, a, b) => (v < a ? a : v > b ? b : v)
const approach = (v, target, delta) => {
  if (v < target) return Math.min(v + delta, target)
  if (v > target) return Math.max(v - delta, target)
  return v
}

function hash(x, y) {
  let h = x * 374761393 + y * 668265263
  h = (h ^ (h >> 13)) * 1274126177
  return ((h ^ (h >> 16)) >>> 0) / 4294967296
}

class Player {
  constructor(x, y) {
    this.w = 10
    this.h = 20
    this.reset(x, y)
  }

  reset(x, y) {
    this.x = x
    this.y = y
    this.vx = 0
    this.vy = 0
    this.onGround = false
    this.coyote = 0
    this.jumpBuffer = 0
    this.prevJump = false
    this.facing = 1
    this.runAnim = 0
    this.landSquash = 0
    this.invuln = 0
    this.shield = false
    this.dead = false
    this.deadTimer = 0
    this.standingOn = null
    this.prevBottom = y + this.h
    this.stepOffset = 0
  }

  update(dt, game) {
    if (this.dead) {
      this.deadTimer += dt
      this.vy = Math.min(this.vy + GRAVITY * dt, MAX_FALL)
      this.y += this.vy * dt
      return
    }

    const input = game.input
    this.invuln = Math.max(0, this.invuln - dt)
    this.landSquash = Math.max(0, this.landSquash - dt * 5)
    this.prevBottom = this.y + this.h

    const dir = (input.right ? 1 : 0) - (input.left ? 1 : 0)
    const maxSpeed = input.run ? 246 : 156
    const accel = this.onGround ? 1500 : 950

    if (dir !== 0) {
      this.vx = approach(this.vx, dir * maxSpeed, accel * dt)
      this.facing = dir
    } else {
      this.vx = approach(this.vx, 0, (this.onGround ? 2000 : 420) * dt)
    }

    if (Math.abs(this.vx) > 12) this.runAnim += dt * (3 + Math.abs(this.vx) * 0.055)

    this.coyote = this.onGround ? 0.1 : Math.max(0, this.coyote - dt)
    this.jumpBuffer = Math.max(0, this.jumpBuffer - dt)
    const jumpPressed = input.jump && !this.prevJump
    this.prevJump = input.jump
    if (jumpPressed) this.jumpBuffer = 0.12

    if (this.jumpBuffer > 0 && this.coyote > 0) {
      this.vy = -432
      this.onGround = false
      this.standingOn = null
      this.coyote = 0
      this.jumpBuffer = 0
      this.landSquash = 0
      game.audio.jump()
      game.spawnDust(this.x + this.w / 2, this.y + this.h, 4)
    }

    if (!input.jump && this.vy < -150) this.vy = -150
    this.vy = Math.min(this.vy + (this.vy < 0 ? 1280 : 1580) * dt, MAX_FALL)

    // Movimiento y colisiones
    const wasGround = this.onGround
    const fallSpeed = this.vy
    this.onGround = false

    if (this.vx !== 0) {
      const hitWall = game.moveEntityX(this, this.vx * dt)
      if (hitWall) this.vx = 0
    }

    const landed = game.moveEntityY(this, this.vy * dt, true)
    if (landed) {
      if (fallSpeed > 220) {
        this.landSquash = Math.min(1, fallSpeed / 700)
        game.spawnDust(this.x + this.w / 2, this.y + this.h, 6)
        game.shake = Math.max(game.shake, 1.2)
      }
      this.vy = 0
      this.onGround = true
    }

    if (!this.onGround && wasGround) this.coyote = Math.max(this.coyote, 0.1)

    if (this.y > VIEW_H + 40) game.killPlayer('pit')
  }

  hit(game) {
    if (this.dead || this.invuln > 0) return
    if (this.shield) {
      this.shield = false
      this.invuln = 1.4
      this.vy = -220
      this.vx = -this.facing * 130
      game.audio.shieldPop()
      game.shake = Math.max(game.shake, 4)
      game.burst(this.x + this.w / 2, this.y + 10, '#9fe8ff', 14)
      game.addText(this.x + this.w / 2, this.y - 6, '¡BURBUJA!', '#9fe8ff')
      return
    }
    game.killPlayer('enemy')
  }
}

const ENEMY_DEFS = {
  grumo: { w: 13, h: 12, score: 200, stompable: true },
  salto: { w: 13, h: 12, score: 300, stompable: true },
  mosca: { w: 12, h: 10, score: 250, stompable: true },
}

class Enemy {
  constructor(type, spawn) {
    const def = ENEMY_DEFS[type]
    this.type = type
    this.w = def.w
    this.h = def.h
    this.score = def.score
    this.stompable = def.stompable
    this.x = spawn.x
    this.y = spawn.y - this.h
    this.spawnX = this.x
    this.spawnY = this.y
    this.vx = 0
    this.vy = 0
    this.dir = Math.random() > 0.5 ? 1 : -1
    this.t = Math.random() * 3
    this.hopTimer = 0.6 + Math.random() * 0.8
    this.onGround = false
    this.dying = false
    this.dyingT = 0
    this.dead = false
    this.squashed = false
    this.wings = Math.random() * 6
    if (type === 'mosca') {
      this.dir = Math.random() > 0.5 ? 1 : -1
      this.range = 54
    }
  }

  update(dt, game) {
    this.t += dt
    this.wings += dt * 22

    if (this.dying) {
      this.dyingT += dt
      if (this.type === 'mosca') {
        this.vy += GRAVITY * 0.7 * dt
        this.y += this.vy * dt
        this.x += this.vx * dt
      }
      if (this.dyingT > 0.5 || this.y > VIEW_H + 40) this.dead = true
      return
    }

    if (this.type === 'grumo') {
      this.vy = Math.min(this.vy + GRAVITY * dt, MAX_FALL)
      const oldX = this.x
      if (game.moveEntityX(this, this.dir * 38 * dt)) this.dir *= -1
      if (this.onGround) {
        const aheadX = this.dir > 0 ? this.x + this.w + 2 : this.x - 2
        const footY = this.y + this.h + 2
        if (!game.isSolidAt(aheadX, footY) && !game.isPlatformAt(aheadX, footY)) this.dir *= -1
      }
      const landed = game.moveEntityY(this, this.vy * dt, true)
      if (landed) {
        this.vy = 0
        this.onGround = true
      } else {
        this.onGround = false
      }
      if (Math.abs(this.x - oldX) < 0.01) this.dir *= -1
    } else if (this.type === 'salto') {
      this.vy = Math.min(this.vy + GRAVITY * dt, MAX_FALL)
      if (game.moveEntityX(this, this.vx * dt)) {
        this.vx *= -0.6
        this.dir *= -1
      }
      const landed = game.moveEntityY(this, this.vy * dt, true)
      if (landed) {
        this.vy = 0
        this.onGround = true
      } else {
        this.onGround = false
      }
      if (this.onGround) {
        this.vx = approach(this.vx, 0, 500 * dt)
        this.hopTimer -= dt
        if (this.hopTimer <= 0) {
          const dx = game.player.x - this.x
          if (Math.abs(dx) < 220) this.dir = dx > 0 ? 1 : -1
          this.vy = -310
          this.vx = this.dir * 92
          this.onGround = false
          this.hopTimer = 1.25 + Math.random() * 0.6
          game.spawnDust(this.x + this.w / 2, this.y + this.h, 3)
        }
      }
    } else if (this.type === 'mosca') {
      this.x = this.spawnX + Math.sin(this.t * 0.9 + this.wings * 0.1) * this.range
      this.y = this.spawnY + Math.sin(this.t * 2.4) * 13
    }

    if (this.y > VIEW_H + 60) this.dead = true
  }

  stomp(game) {
    if (!this.stompable || this.dying) return
    this.dying = true
    this.dyingT = 0
    this.squashed = this.type !== 'mosca'
    this.vx = 0
    this.vy = this.type === 'mosca' ? -80 : 0
    game.score += this.score
    game.addText(this.x + this.w / 2, this.y - 4, `+${this.score}`, '#ffe58a')
    game.burst(this.x + this.w / 2, this.y + this.h / 2, this.type === 'mosca' ? '#d9b3ff' : '#e59a5c', 10)
    game.audio.stomp()
    game.freeze = Math.max(game.freeze, 0.045)
    game.shake = Math.max(game.shake, 2.5)
  }
}

input.oldString:
    game.shake = Math.max(game.shake, 2.5)
  }
}

input.newString:
    game.shake = Math.max(game.shake, 2.5)
  }
}

export class Game {
  constructor(canvas, ui, audio) {
    this.canvas = canvas
    this.ctx = canvas.getContext('2d')
    this.ctx.imageSmoothingEnabled = false
    this.art = createArt()
    this.ui = ui
    this.audio = audio
    this.state = 'title'
    this.input = { left: false, right: false, jump: false, run: false }
    this.time = 0
    this.acc = 0
    this.best = Number(localStorage.getItem('sapobros.best') || 0)
    this.resetWorld()
    this.state = 'title'
    this.ui.setBest(this.best)
  }

  resetWorld() {
    const level = createLevel()
    this.level = level
    this.player = new Player(level.spawn.x, level.spawn.y)
    this.coins = level.coins.map((c, i) => ({ ...c, phase: i * 0.7, taken: false }))
    this.enemies = level.enemies.map((s) => new Enemy(s.type, s))
    this.platforms = level.platforms.map((p) => ({ ...p, x: p.ox, y: p.oy, dx: 0, dy: 0 }))
    this.checkpoints = level.checkpoints.map((c) => ({ ...c }))
    this.particles = []
    this.texts = []
    this.powerups = []
    this.bumps = new Map()
    this.camera = { x: 0 }
    this.checkpoint = { x: level.spawn.x, y: level.spawn.y, time: 300 }
    this.score = 0
    this.coinsCount = 0
    this.lives = 3
    this.timeLeft = 300
    this.shake = 0
    this.freeze = 0
    this.deathT = 0
    this.victoryTimer = 0
    this.confettiTimer = 0
    this.won = false
    this.lastHud = ''
  }

  startRun() {
    this.resetWorld()
    this.state = 'playing'
    this.acc = 0
    this.ui.showScreen(null)
    this.ui.setPlaying(true)
    this.ui.setHud(this.hudData())
    this.audio.unlock()
    this.audio.startMusic()
  }

  togglePause() {
    if (this.state === 'playing') {
      this.state = 'paused'
      this.ui.showScreen('pause')
      this.audio.stopMusic()
    } else if (this.state === 'paused') {
      this.state = 'playing'
      this.ui.showScreen(null)
      this.audio.startMusic()
    }
  }

  backToTitle() {
    this.resetWorld()
    this.state = 'title'
    this.ui.showScreen('title')
    this.ui.setPlaying(false)
    this.audio.stopMusic()
  }

  frame(dt) {
    this.time += dt
    if (this.state === 'paused') {
      this.render()
      return
    }
    if (this.state === 'title') {
      this.updateTitle(dt)
      this.render()
      return
    }
    this.acc += Math.min(dt, 0.1)
    let guard = 0
    while (this.acc >= STEP && guard < 6) {
      this.update(STEP)
      this.acc -= STEP
      guard++
    }
    this.render()
  }

  updateTitle(dt) {
    this.camera.x = 40 + Math.sin(this.time * 0.12) * 40
    this.updatePlatforms(dt)
    this.updateParticles(dt)
    for (const coin of this.coins) coin.phase += dt
  }

  update(dt) {
    const playing = this.state === 'playing'

    if (this.freeze > 0) {
      this.freeze -= dt
    } else {
      if (playing && !this.player.dead) {
        this.timeLeft = Math.max(0, this.timeLeft - dt)
        if (this.timeLeft <= 0) this.killPlayer('time')
      }

      this.updatePlatforms(dt)
      this.player.update(dt, this)

      if (!this.player.dead) {
        this.updateEnemies(dt)
        this.updateCoins(dt)
        this.updatePowerups(dt)
        this.checkHazards()
      }
      this.updateBumps(dt)
      this.updateParticles(dt)
      this.updateTexts(dt)
      this.checkCheckpoints()
      this.checkGoal()
    }

    this.updateCamera(dt)

    if (this.state === 'victory') {
      this.victoryTimer += dt
      this.confettiTimer -= dt
      if (this.confettiTimer <= 0 && this.victoryTimer < 3.2) {
        this.confettiTimer = 0.12
        this.spawnConfetti()
      }
      if (this.victoryTimer > 1.25 && !this.ui.screenShown('victory')) {
        this.ui.showVictory({
          score: this.score,
          coins: this.coinsCount,
          bonus: this.timeBonus || 0,
        })
      }
    }

    if (this.player.dead && playing) {
      this.deathT += dt
      if (this.deathT > 1.45) {
        if (this.lives > 0) this.respawn()
        else this.gameOver()
      }
    }

    this.updateHud()
  }

  hudData() {
    return {
      lives: Math.max(0, this.lives),
      coins: this.coinsCount,
      score: this.score,
      time: Math.ceil(this.timeLeft),
      warn: this.timeLeft < 30 && this.state === 'playing',
    }
  }

  updateHud() {
    const data = this.hudData()
    const key = `${data.lives}|${data.coins}|${data.score}|${data.time}|${data.warn}`
    if (key === this.lastHud) return
    this.lastHud = key
    this.ui.setHud(data)
  }

  updatePlatforms(dt) {
    for (const p of this.platforms) {
      p.dx = 0
      p.dy = 0
      const offset = Math.sin(this.time * (p.speed / Math.max(1, p.range)) + p.phase) * p.range
      const nx = p.axis === 'x' ? p.ox + offset : p.ox
      const ny = p.axis === 'y' ? p.oy + offset : p.oy
      p.dx = nx - p.x
      p.dy = ny - p.y
      p.x = nx
      p.y = ny
    }
    if (this.player.standingOn && this.player.standingOn.type === 'platform') {
      const plat = this.player.standingOn.ref
      if (this.platforms.includes(plat) && !this.player.dead) {
        this.player.x += plat.dx
        this.player.y += plat.dy
      }
    }
  }

  getTile(tx, ty) {
    if (tx < 0 || tx >= 240 || ty < 0 || ty >= 17) return T.EMPTY
    return this.level.tiles[ty * 240 + tx]
  }

  setTile(tx, ty, value) {
    if (tx < 0 || tx >= 240 || ty < 0 || ty >= 17) return
    this.level.tiles[ty * 240 + tx] = value
  }

  isSolidAt(px, py) {
    return SOLID.has(this.getTile(Math.floor(px / TILE), Math.floor(py / TILE)))
  }

  isPlatformAt(px, py) {
    return this.getTile(Math.floor(px / TILE), Math.floor(py / TILE)) === T.PLATFORM
  }

  moveEntityX(ent, dx) {
    ent.x += dx
    if (dx === 0) return false
    const y0 = Math.floor(ent.y / TILE)
    const y1 = Math.floor((ent.y + ent.h - 0.01) / TILE)
    if (dx > 0) {
      const tx = Math.floor((ent.x + ent.w - 0.01) / TILE)
      for (let ty = y0; ty <= y1; ty++) {
        if (SOLID.has(this.getTile(tx, ty))) {
          ent.x = tx * TILE - ent.w
          return true
        }
      }
    } else {
      const tx = Math.floor(ent.x / TILE)
      for (let ty = y0; ty <= y1; ty++) {
        if (SOLID.has(this.getTile(tx, ty))) {
          ent.x = (tx + 1) * TILE
          return true
        }
      }
    }
    return false
  }

  moveEntityY(ent, dy, oneWay = true) {
    const prevBottom = ent.y + ent.h
    ent.y += dy
    if (dy > 0) {
      const ty = Math.floor((ent.y + ent.h - 0.01) / TILE)
      const x0 = Math.floor(ent.x / TILE)
      const x1 = Math.floor((ent.x + ent.w - 0.01) / TILE)
      for (let tx = x0; tx <= x1; tx++) {
        const t = this.getTile(tx, ty)
        if (SOLID.has(t) || (oneWay && t === T.PLATFORM && prevBottom <= ty * TILE + 2)) {
          ent.y = ty * TILE - ent.h
          if (ent === this.player) ent.standingOn = { type: 'tile' }
          return true
        }
      }
      if (oneWay) {
        for (const p of this.platforms) {
          if (ent.x + ent.w > p.x + 1 && ent.x < p.x + p.w - 1) {
            if (prevBottom <= p.y + 2 && ent.y + ent.h >= p.y) {
              ent.y = p.y - ent.h
              if (ent === this.player) ent.standingOn = { type: 'platform', ref: p }
              return true
            }
          }
        }
      }
    } else if (dy < 0) {
      const ty = Math.floor(ent.y / TILE)
      const x0 = Math.floor(ent.x / TILE)
      const x1 = Math.floor((ent.x + ent.w - 0.01) / TILE)
      for (let tx = x0; tx <= x1; tx++) {
        if (SOLID.has(this.getTile(tx, ty))) {
          ent.y = (ty + 1) * TILE
          if (ent === this.player) this.hitBlock(tx, ty)
          return true
        }
      }
    }
    return false
  }

  hitBlock(tx, ty) {
    const t = this.getTile(tx, ty)
    if (t !== T.QUESTION && t !== T.BRICK) return
    const key = `${tx},${ty}`
    this.bumps.set(key, { t: 0 })
    if (t === T.QUESTION) {
      this.setTile(tx, ty, T.USED)
      const power = this.level.powerBlocks.has(ty * 240 + tx)
      if (power) {
        this.spawnPowerup(tx, ty)
        this.audio.power()
      } else {
        this.addCoin(1)
        this.burst(tx * TILE + 8, ty * TILE - 2, '#ffe58a', 7)
        this.addText(tx * TILE + 8, ty * TILE - 6, '+1', '#ffe58a')
        this.audio.coin()
      }
      this.score += 50
    } else if (t === T.BRICK) {
      if (this.player.shield) {
        this.setTile(tx, ty, T.EMPTY)
        this.burst(tx * TILE + 8, ty * TILE + 8, '#e08a5e', 12)
        this.burst(tx * TILE + 8, ty * TILE + 8, '#c65f3d', 8)
        this.audio.brick()
        this.score += 50
        this.shake = Math.max(this.shake, 3)
      } else {
        this.audio.bump()
      }
    }
  }

  spawnPowerup(tx, ty) {
    this.powerups.push({
      x: tx * TILE + 8,
      y: ty * TILE - 2,
      baseY: ty * TILE - 2,
      vy: -55,
      t: 0,
      taken: false,
    })
  }

  updatePowerups(dt) {
    for (const p of this.powerups) {
      if (p.taken) continue
      p.t += dt
      p.y += p.vy * dt
      p.vy = approach(p.vy, -14, 120 * dt)
      if (p.y < p.baseY - 30) p.vy = Math.max(p.vy, 0)
      const r = 11
      if (
        this.player.x + this.player.w > p.x - r &&
        this.player.x < p.x + r &&
        this.player.y + this.player.h > p.y - r - 6 &&
        this.player.y < p.y + r
      ) {
        p.taken = true
        if (!this.player.shield) {
          this.player.shield = true
          this.addText(p.x, p.y - 14, '¡BURBUJA!', '#9fe8ff')
        } else {
          this.addText(p.x, p.y - 14, '+500', '#ffe58a')
        }
        this.score += 500
        this.audio.power()
        this.burst(p.x, p.y, '#9fe8ff', 14)
      }
    }
    this.powerups = this.powerups.filter((p) => !p.taken || p.t < 0.4)
  }

